// ===== EDIT THESE TWO LINES =====
const ALLOWED_CHAT_IDS = ['REPLACE_WITH_MANAGER_CHAT_ID']; // send /myid to the bot to find a chat ID
const MANAGER_EMAIL = 'pv191130@gmail.com';
const MUTE_ALERT_EMAILS_DURING_FILE_IMPORT = true; // true: no per-row low-stock emails for file imports (they are listed in the summary instead)
// ================================
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const msg = $input.first().json.message || {};
const chatId = msg.chat && msg.chat.id !== undefined ? String(msg.chat.id) : '';
const text = String(msg.text || msg.caption || '').trim();
const lower = text.toLowerCase();
const who = msg.from ? [msg.from.first_name, msg.from.last_name].filter(Boolean).join(' ') || msg.from.username || '' : '';
const base = { chat_id: chatId, manager_email: MANAGER_EMAIL, requester: who, dry_run: false, is_single: false, suppress_alerts: false, query_type: '', query_term: '', rows: [], update_id: '', file_id: '', file_name: '', ext: '', reply_text: '', ack_text: '' };

if (lower.startsWith('/myid')) return [{ json: Object.assign(base, { route: 'reply', reply_text: 'Your chat ID is ' + esc(chatId) + '. Give this number to whoever manages the workflow so you can be authorised.' }) }];
if (!ALLOWED_CHAT_IDS.map(String).includes(chatId)) return [{ json: Object.assign(base, { route: 'reply', reply_text: 'Sorry, this chat is not authorised to change inventory. Send /myid to get your chat ID and ask the administrator to add it.' }) }];

const help = 'Inventory bot\n\n' +
  'Quick changes: just type a message\n' +
  '  add 20 bread\n  remove 5 milk\n  set 30 bread\n  create Bottled Water 100 bottle 20\n' +
  'You can use a Product ID instead of a name, e.g. add 20 P001.\n' +
  'Start with dry run to test without changing anything, e.g. dry run remove 5 milk.\n\n' +
  'Questions you can ask:\n  stock bread  (or: how much bread do we have?)\n  low stock\n  list\n  history  or  history bread\n\n' +
  'Bulk changes: send a CSV or Excel file (.csv, .xls, .xlsx) as a File (paperclip, File).\n' +
  'Columns: Action, Product ID, Item name, Quantity, Unit, Reorder level, Request ID (optional).\n' +
  'Put dry run in the caption to check a file without changing stock.';
const doc = msg.document;
if (!doc) {
  const updateId = $input.first().json.update_id;
  let s = text.replace(/^\/(?=\w)/, '').replace(/^(\w+)@\w+/, '$1').trim();
  let dry = false;
  const dm = s.match(/^dry[\s_-]?run\s*:?\s+(.*)$/i);
  if (dm) { dry = true; s = dm[1].trim(); }
  const q = (() => {
    const clean = t => t.replace(/\?+$/, '').replace(/\b(do we have|is left|are left|in stock|remaining|left)\b/ig, '').replace(/\s+/g, ' ').trim();
    let mm;
    if (/^(low|low[\s-]?stock|what(?:'s| is| are)? (?:running )?low|running low|reorder)\b/i.test(s)) return { type: 'low', term: '' };
    if (/^(list|inventory|all stock|stock list|all|stock|report)\??$/i.test(s)) return { type: 'list', term: '' };
    if ((mm = s.match(/^(?:history|log|recent|changes)(?:\s+(.+))?$/i))) return { type: 'history', term: mm[1] ? clean(mm[1]) : '' };
    if ((mm = s.match(/^(?:stock|check|qty|level)\s+(?:of\s+)?(.+)$/i))) return { type: 'stock', term: clean(mm[1]) };
    if ((mm = s.match(/^(?:how much|how many)\s+(.+)$/i))) return { type: 'stock', term: clean(mm[1]) };
    if ((mm = s.match(/^do we have\s+(.+)$/i))) return { type: 'stock', term: clean(mm[1]) };
    return null;
  })();
  if (q) return [{ json: Object.assign(base, { route: 'query', query_type: q.type, query_term: q.term }) }];
  const mkRow = (action, qty, name, unit, reorder) => {
    const n = name.trim();
    const isId = /^P\d+$/i.test(n);
    return { 'Action': action.toLowerCase(), 'Product ID': isId ? n.toUpperCase() : '', 'Item name': isId ? '' : n,
             'Quantity': qty, 'Unit': unit || '', 'Reorder level': reorder || '', 'Request ID': 'TG-' + updateId };
  };
  let row = null, m;
  if ((m = s.match(/^(add|remove|set)\s+(\d+(?:\.\d+)?)\s+(.+)$/i))) row = mkRow(m[1], m[2], m[3]);
  else if ((m = s.match(/^(add|remove|set)\s+(.+?)\s+(\d+(?:\.\d+)?)$/i))) row = mkRow(m[1], m[3], m[2]);
  else if ((m = s.match(/^create\s+(.+?)\s+(\d+(?:\.\d+)?)\s+(\S+)\s+(\d+(?:\.\d+)?)$/i))) row = mkRow('create', m[2], m[1], m[3], m[4]);
  if (!row) {
    const looksLikeCommand = /^(add|remove|set|create)\b/i.test(s);
    return [{ json: Object.assign(base, { route: 'reply', reply_text: (looksLikeCommand ? 'I could not read that command.\n\n' : '') + help }) }];
  }
  return [{ json: Object.assign(base, { route: 'single', dry_run: dry, is_single: true, rows: [row], file_name: 'Chat command', update_id: String(updateId) }) }];
}

const fileName = String(doc.file_name || '');
const ext = fileName.split('.').pop().toLowerCase();
if (!['csv', 'xls', 'xlsx'].includes(ext)) return [{ json: Object.assign(base, { route: 'reply', reply_text: 'I can only read .csv, .xls or .xlsx files. Received: ' + esc(fileName || 'unknown file') }) }];

const dry = /dry[\s_-]?run|validate only|test only/.test(lower);
return [{ json: Object.assign(base, {
  route: 'import', dry_run: dry, suppress_alerts: MUTE_ALERT_EMAILS_DURING_FILE_IMPORT, file_id: doc.file_id, file_name: fileName, ext,
  ack_text: (dry ? 'Dry run: checking ' : 'Importing ') + esc(fileName) + (dry ? ' (no stock will be changed)...' : '...') + ' I will message you when it is done.'
}) }];

const route = $('Route Message').first().json;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const str = v => (v === null || v === undefined) ? '' : String(v).trim();
const norm = v => str(v).toLowerCase();
const num = v => { const n = Number(String(v === null || v === undefined ? '' : v).replace(/,/g, '')); return Number.isFinite(n) ? n : NaN; };
const inv = $('Query Read Inventory').all().map(i => i.json).filter(r => str(r['Product ID']) !== '').map(r => ({
  id: str(r['Product ID']), name: str(r['Item name']), qty: str(r['Quantity']), unit: str(r['Unit']),
  reorder: str(r['Reorder level']), updated: str(r['Updated at'])
}));
const isLow = p => { const q = num(p.qty), r = num(p.reorder); return Number.isFinite(q) && Number.isFinite(r) && q <= r; };
const line = p => p.name + ' (' + p.id + '): ' + p.qty + ' ' + p.unit + (isLow(p) ? ' - LOW, reorder level ' + p.reorder : (p.reorder ? ' - reorder level ' + p.reorder : ''));
const cap = (arr, max) => { let out = '', n = 0; for (const l of arr) { if ((out + '\n' + l).length > max) break; out += (out ? '\n' : '') + l; n++; } return out + (n < arr.length ? '\n...and ' + (arr.length - n) + ' more.' : ''); };
const type = route.query_type, term = norm(route.query_term);
let text = '';

if (inv.length === 0 && type !== 'history') {
  text = 'The inventory is empty.';
} else if (type === 'low') {
  const low = inv.filter(isLow);
  text = low.length ? 'Low stock (' + low.length + ' of ' + inv.length + ' products):\n' + cap(low.map(line), 3600) : 'Nothing is at or below its reorder level. ' + inv.length + ' products checked.';
} else if (type === 'list') {
  text = 'Inventory (' + inv.length + ' products):\n' + cap(inv.map(line), 3600);
} else if (type === 'stock') {
  if (!term) { text = 'Tell me which product, e.g. stock bread.'; }
  else {
    let hit = inv.filter(p => norm(p.id) === term || norm(p.name) === term);
    if (hit.length === 0) hit = inv.filter(p => norm(p.name).includes(term) || term.includes(norm(p.name)) || norm(p.id).includes(term));
    if (hit.length === 0) text = 'No product found for "' + route.query_term + '". Send list to see everything.';
    else if (hit.length === 1) text = line(hit[0]) + (hit[0].updated ? '\nLast updated: ' + hit[0].updated : '');
    else text = 'Matches for "' + route.query_term + '":\n' + cap(hit.map(line), 3600);
  }
} else if (type === 'history') {
  const log = $input.all().map(i => i.json).filter(r => str(r['Request ID']) !== '' || str(r['Timestamp']) !== '');
  let rows = log.slice().reverse();
  if (term) rows = rows.filter(r => norm(r['Item name']).includes(term) || norm(r['Product ID']) === term);
  rows = rows.slice(0, 10);
  if (rows.length === 0) text = term ? 'No history found for "' + route.query_term + '".' : 'The change log is empty.';
  else {
    const fmt = r => {
      const when = str(r['Timestamp']).slice(0, 16);
      const who = str(r['Item name']) || str(r['Product ID']) || '-';
      if (norm(r['Status']) === 'success') {
        const ch = str(r['Change quantity']);
        return when + ' ' + who + ' ' + str(r['Action']) + (ch ? ' (' + ch + ')' : '') + (str(r['New quantity']) ? ' -> ' + str(r['New quantity']) : '') + ' OK';
      }
      return when + ' ' + who + ' ' + str(r['Action']) + ' REJECTED: ' + str(r['Message']).slice(0, 80);
    };
    text = (term ? 'Recent changes for "' + route.query_term + '"' : 'Recent changes') + ' (newest first):\n' + cap(rows.map(fmt), 3600);
  }
}
return [{ json: { chat_id: route.chat_id, reply_text: esc(text) } }];

const rows = $input.all().map(i => i.json);
const fileName = $('Route Message').first().json.file_name;
const text = JSON.stringify(rows);
let h = 5381;
for (let i = 0; i < text.length; i++) { h = ((h * 33) ^ text.charCodeAt(i)) >>> 0; }
const sig = h.toString(36).toUpperCase();
return [{ json: { rows, file_name: fileName, file_sig: sig } }];

const route = $('Route Message').first().json;
const dry = !!route.dry_run;
let collected;
try { collected = $('Single Command').first().json; } catch (e) { collected = $('Collect Rows').first().json; }
const sig = collected.file_sig;
const rows = collected.rows || [];
const MAX_ROWS = 500;
const now = $now.toFormat('yyyy-MM-dd HH:mm:ss');
const str = v => (v === null || v === undefined) ? '' : String(v).trim();
const norm = v => str(v).toLowerCase();
const keyOf = k => String(k).toLowerCase().replace(/[^a-z0-9]/g, '');
const get = (row, ...names) => { for (const k of Object.keys(row)) { if (names.includes(keyOf(k))) return row[k]; } return ''; };
const parseNum = v => { const s = String(v === null || v === undefined ? '' : v).replace(/,/g, '').replace(/[^0-9.\-]/g, ''); if (s === '' || s === '-' || s === '.') return NaN; return Number(s); };

// Only rows that already SUCCEEDED block a re-upload; rejected rows may be retried.
const done = new Set($('Read Change Log').all().map(i => i.json)
  .filter(r => norm(r['Status']) === 'success')
  .map(r => str(r['Request ID'])).filter(Boolean));

// Working copy of inventory so later rows in the file see the effect of earlier ones.
const inv = $input.all().map(i => i.json).filter(r => str(r['Product ID']) !== '').map(r => ({
  id: str(r['Product ID']), name: str(r['Item name']), qty: parseNum(r['Quantity']),
  unit: str(r['Unit']), reorder: parseNum(r['Reorder level'])
}));

const mk = o => ({ json: Object.assign({
  row_number: '', request_id: '', source: 'Telegram Bulk Upload', action: '', timestamp: now,
  product_id: '', item_name: '', quantity: '', unit: '', reorder_level: '',
  pre_rejected: false, status: '', message: '', file_name: collected.file_name,
  dry_run: dry, sim_status: '', sim_message: ''
}, o) });
const fail = (base, msg, pre) => mk(Object.assign({}, base, { pre_rejected: !!pre, status: 'Rejected', message: msg, sim_status: 'Rejected', sim_message: msg }));

if (rows.length === 0) return [fail({ action: 'bulk', request_id: 'BULK-' + sig + '-EMPTY' }, 'The uploaded file has no data rows.', true)];
if (rows.length > MAX_ROWS) return [fail({ action: 'bulk', request_id: 'BULK-' + sig + '-TOOBIG' }, 'The file has ' + rows.length + ' rows; the limit is ' + MAX_ROWS + '. Nothing was processed.', true)];

const generic = ['', 'unit', 'units', 'item', 'items', 'pc', 'pcs', 'piece', 'pieces'];
const listP = l => l.map(p => p.id + ' ' + p.name + ' (' + p.qty + ' ' + p.unit + ')').join(', ');
const out = [];
const seen = new Set();

rows.forEach((row, idx) => {
  const n = idx + 2;
  if (Object.values(row).every(v => str(v) === '')) return;
  const requestId = str(get(row, 'requestid')) || ('BULK-' + sig + '-R' + n);
  const base = {
    row_number: n, request_id: requestId, action: norm(get(row, 'action')),
    product_id: str(get(row, 'productid')),
    item_name: str(get(row, 'itemname', 'item', 'product', 'productname')),
    quantity: str(get(row, 'quantity', 'qty')), unit: str(get(row, 'unit')),
    reorder_level: str(get(row, 'reorderlevel', 'reorder'))
  };
  if (done.has(requestId)) { out.push(fail(base, 'Duplicate: Request ID ' + requestId + ' was already processed successfully. Row skipped.', true)); return; }
  if (seen.has(requestId)) { out.push(fail(base, 'Duplicate Request ID ' + requestId + ' appears more than once in this file. Row skipped.', true)); return; }
  seen.add(requestId);

  const action = base.action;
  if (!['set', 'add', 'remove', 'create'].includes(action)) { out.push(fail(base, 'Unknown action "' + str(get(row, 'action')) + '". Use set, add, remove or create.', false)); return; }
  const qty = parseNum(base.quantity);
  if (!Number.isFinite(qty)) { out.push(fail(base, 'The quantity is missing or not a number.', false)); return; }
  if ((action === 'set' || action === 'create') && qty < 0) { out.push(fail(base, 'Stock cannot be negative.', false)); return; }
  if ((action === 'add' || action === 'remove') && qty <= 0) { out.push(fail(base, 'The quantity to ' + action + ' must be greater than zero.', false)); return; }

  if (action === 'create') {
    if (!base.item_name) { out.push(fail(base, 'A product name is required to register a new product.', false)); return; }
    if (!base.unit) { out.push(fail(base, 'A unit (e.g. loaf, litre, crate) is required to register a new product.', false)); return; }
    const reorder = parseNum(base.reorder_level);
    if (!Number.isFinite(reorder) || reorder < 0) { out.push(fail(base, 'A valid reorder level (0 or more) is required to register a new product.', false)); return; }
    const dup = inv.filter(p => norm(p.name) === norm(base.item_name) || (base.product_id && norm(p.id) === norm(base.product_id)));
    if (dup.length) { out.push(fail(base, 'This product already exists: ' + listP(dup) + '. No new row was created.', false)); return; }
    let maxN = 0;
    inv.forEach(p => { const m = p.id.match(/(\d+)$/); if (m) maxN = Math.max(maxN, Number(m[1])); });
    const newId = 'P' + String(maxN + 1).padStart(3, '0');
    inv.push({ id: newId, name: base.item_name, qty, unit: base.unit, reorder });
    const low = qty <= reorder;
    out.push(mk(Object.assign({}, base, { product_id: '', sim_status: 'OK', sim_message: 'Would register ' + base.item_name + ' as ' + newId + ' with ' + qty + ' ' + base.unit + (low ? ' (LOW STOCK)' : '') })));
    return;
  }

  // update actions: resolve by Product ID, else by exact name
  let matches = [];
  if (base.product_id) matches = inv.filter(p => norm(p.id) === norm(base.product_id));
  else if (base.item_name) matches = inv.filter(p => norm(p.name) === norm(base.item_name));
  else { out.push(fail(base, 'No product specified. Give a Product ID or the exact Item name.', true)); return; }
  if (matches.length === 0) {
    const term = base.product_id || base.item_name;
    const nm = norm(base.item_name);
    const partial = nm ? inv.filter(p => norm(p.name).includes(nm) || nm.includes(norm(p.name))) : [];
    out.push(fail(base, 'Product not found: "' + term + '".' + (partial.length ? ' Possible matches: ' + listP(partial) + '.' : '') + ' Nothing was changed.', true)); return;
  }
  if (matches.length > 1) { out.push(fail(base, 'More than one inventory row matches: ' + listP(matches) + '. Use the Product ID. Nothing was changed.', true)); return; }
  const p = matches[0];
  base.product_id = p.id; base.item_name = p.name; // resolved, so the engine gets an exact ID
  if (!Number.isFinite(p.qty)) { out.push(fail(base, 'The current stock for ' + p.name + ' in the sheet is not a valid number. Fix the sheet before updating.', false)); return; }
  const unitReq = norm(base.unit); const rowUnit = norm(p.unit);
  if (!generic.includes(unitReq) && rowUnit && unitReq.slice(0, 3) !== rowUnit.slice(0, 3)) { out.push(fail(base, 'Unit mismatch: ' + p.name + ' is tracked in ' + p.unit + ', but the row used "' + base.unit + '".', false)); return; }
  let newQty;
  if (action === 'set') newQty = qty; else if (action === 'add') newQty = p.qty + qty; else newQty = p.qty - qty;
  if (newQty < 0) { out.push(fail(base, 'Only ' + p.qty + ' ' + p.unit + ' of ' + p.name + ' available, cannot remove ' + qty + '. Nothing was changed.', false)); return; }
  const prev = p.qty; p.qty = newQty;
  const low = Number.isFinite(p.reorder) && newQty <= p.reorder;
  out.push(mk(Object.assign({}, base, { sim_status: 'OK', sim_message: 'Would ' + action + ' ' + qty + ' ' + p.unit + ': ' + prev + ' -> ' + newQty + (low ? ' (LOW STOCK)' : '') })));
});

if (out.length === 0) return [fail({ action: 'bulk', request_id: 'BULK-' + sig + '-EMPTY' }, 'The uploaded file has no data rows.', true)];
return out;

const route = $('Route Message').first().json;
const dry = !!route.dry_run;
const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const prep = $('Prepare Rows').all().map(i => i.json);
const details = [];
let ok = 0, rej = 0;
const lowItems = [];
if (dry) {
  prep.forEach(r => {
    const good = r.sim_status === 'OK';
    if (good) ok++; else rej++;
    details.push({ row: r.row_number, good, item: r.item_name || r.product_id, message: r.sim_message });
  });
} else {
  const pre = prep.filter(r => r.pre_rejected);
  const toRun = prep.filter(r => !r.pre_rejected);
  let results = [];
  try { results = $('Call Engine').all().map(i => i.json); } catch (e) { results = []; }
  pre.forEach(r => { rej++; details.push({ row: r.row_number, good: false, item: r.item_name || r.product_id, message: r.message }); });
  toRun.forEach((r, i) => {
    const res = results[i] || {};
    const good = res.status === 'Success';
    if (good) ok++; else rej++;
    if (good && res.low_stock) lowItems.push((res.item_name || r.item_name) + ': ' + res.new_quantity + ' ' + (res.unit || '') + ' (reorder level ' + res.reorder_level + ')');
    details.push({ row: r.row_number, good, item: res.item_name || r.item_name || r.product_id, message: res.message || res.error || 'No response from the Inventory Stock Update Engine for this row.' });
  });
}
details.sort((a, b) => Number(a.row || 0) - Number(b.row || 0));
if (route.is_single && details.length === 1) {
  const d = details[0];
  const t = (dry ? 'DRY RUN - nothing was changed\n' : '') + (d.good ? 'OK: ' : 'REJECTED: ') + d.message;
  return [{ json: { telegram_text: esc(t), email_subject: '', email_body: t, chat_id: route.chat_id, manager_email: route.manager_email, total: 1, ok, rejected: rej, dry_run: dry, is_single: true } }];
}
const fileName = prep.length ? prep[0].file_name : '';
const title = dry ? 'DRY RUN - nothing was changed' : 'Import finished';
const okWord = dry ? 'Would succeed' : 'Succeeded';
const rejWord = dry ? 'Would be rejected' : 'Rejected';
const head = [title, 'File: ' + fileName, 'Rows: ' + details.length, okWord + ': ' + ok, rejWord + ': ' + rej, ''];
const lines = details.map(d => 'Row ' + d.row + (d.good ? ' OK' : ' REJECTED') + (d.item ? ' - ' + d.item : '') + ': ' + d.message);
const lowText = lowItems.length ? '\n\nLow stock after this import:\n' + lowItems.map(x => '- ' + x).join('\n') : '';
const footer = lowText + (dry ? '\nIf this looks right, send the same file again without "dry run" to apply it.' : '');
const emailBody = head.join('\n') + lines.join('\n') + footer;
let tg = head.join('\n'); const room = Math.max(1500, 3700 - footer.length);
let shown = 0;
for (const l of lines) { if ((tg + '\n' + l).length > room) break; tg += '\n' + l; shown++; }
if (shown < lines.length) tg += '\n...and ' + (lines.length - shown) + ' more rows (see the email for the full list).';
tg += footer;
return [{ json: {
  telegram_text: esc(tg),
  email_subject: (dry ? '[DRY RUN] ' : '') + 'Bulk inventory import: ' + fileName + ' (' + ok + ' ok, ' + rej + ' rejected)',
  email_body: emailBody, chat_id: route.chat_id, manager_email: route.manager_email,
  total: details.length, ok, rejected: rej, dry_run: dry, is_single: false
} }];
